function matrixSignal(s,o){let direct=(o.story||[]).includes(s.id)||relationDecision(s.id,o.id)==="concluido",shared=(o.themes||[]).filter(t=>(s.themes||[]).includes(t)),deadline=o.deadline?days(o.deadline):null,stage=storyStage(s),personal=editorialState("opportunity",o.id)?.state||"",score=(direct?5:0)+shared.length*2+(o.fit>=9?2:o.fit>=8?1:0)+(personal==="vou_fazer"?2:personal==="em_andamento"?3:0)+(deadline!==null&&deadline>=0&&deadline<=30?2:0);return{direct,shared,deadline,stage,personal,score}}
function matrix(){let active=D.opportunities.filter(o=>!["encerrada","descartada"].includes(o.status)&&o.eligibility!=="inelegível"&&editorialState("opportunity",o.id)?.state!=="sem_interesse"),stories=D.stories.filter(s=>storyStage(s)!=="sem_interesse"),signals=stories.flatMap(s=>active.map(o=>({s,o,m:matrixSignal(s,o)}))).filter(x=>x.m.direct||x.m.shared.length),actionable=signals.filter(x=>x.m.direct&&["vou_fazer","em_andamento"].includes(x.m.personal)),urgent=signals.filter(x=>x.m.direct&&x.m.deadline!==null&&x.m.deadline>=0&&x.m.deadline<=30),thematic=signals.filter(x=>!x.m.direct&&x.m.shared.length>=2).sort((a,b)=>b.m.score-a.m.score),withActiveLink=new Set(signals.filter(x=>x.m.direct).map(x=>x.s.id)).size;let rows=stories.map(s=>{let rel=signals.filter(x=>x.s.id===s.id).sort((a,b)=>b.m.score-a.m.score),direct=rel.filter(x=>x.m.direct),suggest=rel.filter(x=>!x.m.direct&&relationDecision(s.id,x.o.id)!=="sem_interesse").slice(0,3);return'<section class="matchstory"><div class="matchstoryhead"><div><div class="eyebrow">'+(s.status||"Pauta")+'</div><h2><a href="#pauta/'+s.id+'">'+s.title+'</a> '+stateMark("story",s.id)+'</h2></div><div class="matchcount">'+direct.length+' vínculo(s)</div></div><div class="matchcols"><div><h3>Oportunidades vinculadas</h3>'+(direct.length?direct.map(x=>matrixOpportunity(x,true)).join(""):'<p class="meta">Nenhuma oportunidade ativa vinculada.</p>')+'</div><div><h3>Relações temáticas descobertas</h3>'+(suggest.length?suggest.map(x=>matrixOpportunity(x,false)).join(""):'<p class="meta">Nenhuma relação temática adicional visível.</p>')+'</div></div></section>'}).join("");return head("Compatibilidade","Pautas × oportunidades","Painel para acompanhar vínculos cadastrados, prazos e relações temáticas descobertas pelo Radar. As relações podem permanecer sem decisão pelo tempo que for necessário.")+'<div class="metrics matchmetrics"><div class="metric"><b>'+actionable.length+'</b><span>vínculos em execução</span></div><div class="metric"><b>'+urgent.length+'</b><span>vínculos com prazo ≤ 30 dias</span></div><div class="metric"><b>'+thematic.length+'</b><span>relações temáticas descobertas</span></div><div class="metric"><b>'+withActiveLink+'</b><span>pautas com oportunidade ativa</span></div></div><div class="matchlegend"><span><i class="dot direct"></i> vínculo editorial cadastrado</span><span><i class="dot thematic"></i> relação temática, ainda não vinculada</span></div>'+rows+'<div class="warning"><b>Regra editorial:</b> relações temáticas são apenas descoberta e não geram pendência. Você pode confirmá-las ou ocultá-las quando conhecer melhor a oportunidade; deixar sem decisão não altera nada.</div>'}
