function calendar(){let all=route().split("/")[1]==="todos";if(!all&&!personalReady())return head("Prazos","Calendário","Agenda operacional das oportunidades que você decidiu preparar ou executar.")+'<div class="viewtoggle"><a class="btn primary" href="#calendario">Meu calendário</a><a class="btn" href="#calendario/todos">Todos os prazos</a></div><div class="warning personalunavailable"><b>Estado pessoal indisponível nesta sessão.</b> Use “Todos os prazos” para a consulta factual.</div>';let states=["vou_fazer","em_andamento"],a=D.opportunities.filter(o=>o.deadline&&!["encerrada","descartada"].includes(o.status)&&(all||states.includes(editorialState("opportunity",o.id)?.state))).sort((a,b)=>a.deadline.localeCompare(b.deadline)),groups=[["Até 7 dias",o=>days(o.deadline)>=0&&days(o.deadline)<=7],["8–30 dias",o=>days(o.deadline)>7&&days(o.deadline)<=30],["Depois de 30 dias",o=>days(o.deadline)>30],["Prazo vencido",o=>days(o.deadline)<0]];return head("Prazos","Calendário",all?"Consulta factual de todos os prazos ativos do Radar.":"Agenda operacional das oportunidades que você decidiu preparar ou executar.")+'<div class="viewtoggle"><a class="btn '+(!all?"primary":"")+'" href="#calendario">Meu calendário</a><a class="btn '+(all?"primary":"")+'" href="#calendario/todos">Todos os prazos</a></div>'+(a.length?groups.map(([label,test])=>{let rows=a.filter(test);return rows.length?'<section class="calgroup"><h2>'+label+'</h2><div class="timeline">'+rows.map(o=>'<div class="event"><h3><a href="#oportunidade/'+o.id+'">'+o.title+'</a> '+stateMark("opportunity",o.id)+'</h3><b>'+fmt(o.deadline)+'</b> · '+o.org+'<div class="meta">'+(days(o.deadline)>=0?days(o.deadline)+' dias restantes':'prazo já encerrado')+'</div></div>').join("")+'</div></section>':""}).join(""):'<div class="warning ok"><b>Nenhum prazo pessoal.</b> Marque uma oportunidade como “Vou fazer” ou “Em andamento” para ela aparecer aqui.</div>')}
