function sourceQueue(){return D.sources.filter(sourceDue).sort((a,b)=>sourceUrgency(b)-sourceUrgency(a)||a.name.localeCompare(b.name))}
function methodNav(active="fontes"){return'<div class="exports"><a class="btn '+(active==="fontes"?"primary":"")+'" href="#metodologia">Fontes & método</a><a class="btn '+(active==="ia"?"primary":"")+'" href="#metodologia/ia">IA</a><a class="btn '+(active==="qualidade"?"primary":"")+'" href="#metodologia/qualidade">Qualidade</a><a class="btn '+(active==="mudancas"?"primary":"")+'" href="#metodologia/mudancas">Mudanças técnicas</a></div>'}
function aiMethod(){return head("Metodologia","Uso de IA","Como automação e modelos de IA entram no Radar — e quais decisões continuam dependendo de verificação editorial.")+methodNav("ia")+'<div class="detail"><div class="kv"><b>Descoberta e triagem</b><div>IA pode auxiliar a localizar, resumir, classificar e deduplicar oportunidades, fontes e bases.</div></div><div class="kv"><b>Verificação</b><div>Informação operacional — prazo, elegibilidade, valor, regras e acesso — deve ser conferida na fonte oficial antes de orientar uma decisão.</div></div><div class="kv"><b>Inferência</b><div>Campos desconhecidos permanecem pendentes. O Radar não deve preencher lacunas factuais por inferência do modelo.</div></div><div class="kv"><b>Decisão editorial</b><div>Aderência e relações entre pauta e oportunidade servem à organização; não substituem julgamento editorial nem justificam adaptar artificialmente uma investigação.</div></div><div class="kv"><b>Rastreabilidade</b><div>Alterações estruturais, auditorias e verificações ficam registradas nas áreas internas de Metodologia, sem ocupar a Visão Geral.</div></div></div>'}
function methods(section="fontes"){if(section==="ia")return aiMethod();if(section==="qualidade")return head("Metodologia","Qualidade","Validação estrutural e pendências internas do Radar.")+methodNav("qualidade")+quality(true);if(section==="mudancas")return head("Metodologia","Mudanças técnicas","Histórico de alterações internas, auditorias e verificações.")+methodNav("mudancas")+changes(true);let stats=D.sources.map(s=>({s,stat:sourceStats(s.name)})),high=stats.filter(x=>x.s.priority==="Alta").length,productive=stats.filter(x=>x.stat.hits>0).length,queue=sourceQueue();return head("Metodologia","Fontes & método","Descoberta não equivale a confirmação. O Radar combina web aberta, fontes oficiais, fontes especializadas e Gmail.")+methodNav("fontes")+'<h2>Fluxo editorial</h2><p class="lede">Descoberta → fonte oficial → elegibilidade → deduplicação → classificação → ação → histórico.</p><div class="warning"><b>Aderência ≠ elegibilidade ≠ prontidão.</b> A fonte oficial prevalece; newsletters servem como descoberta.</div><h2>Cobertura das fontes</h2><div class="metrics"><div class="metric"><b>'+D.sources.length+'</b><span>fontes monitoradas</span></div><div class="metric"><b>'+high+'</b><span>alta prioridade</span></div><div class="metric"><b>'+productive+'</b><span>com oportunidade associada</span></div><div class="metric"><b>'+queue.length+'</b><span>checagem vencida</span></div></div><h2>Fila de monitoramento</h2>'+(queue.length?'<div class="list">'+queue.slice(0,12).map(s=>'<div class="row"><div><h3>'+s.name+'</h3><span class="meta">'+s.category+'</span></div><div>'+s.priority+' prioridade</div><div>'+s.cadence+'<div class="meta">última checagem '+(s.lastChecked?fmt(s.lastChecked):"não registrada")+'</div></div><div>'+(s.url?'<a class="btn" target="_blank" rel="noopener" href="'+s.url+'">Checar fonte ↗</a>':'<span class="meta">Checar via Gmail</span>')+'</div></div>').join("")+'</div>':'<div class="warning ok"><b>Monitoramento em dia:</b> nenhuma fonte ultrapassou sua cadência.</div>')+'<h2>Fontes monitoradas</h2><div class="list">'+stats.map(x=>{let s=x.s,z=x.stat;return'<div class="row"><div><h3>'+s.name+'</h3><span class="meta">'+s.type+'</span></div><div>'+s.scope+'<div class="meta">'+s.category+' · '+z.hits+' oportunidade(s)</div></div><div>'+s.priority+' prioridade<div class="meta">monitoramento '+s.cadence+' · fonte checada '+(s.lastChecked?fmt(s.lastChecked):"nunca")+(sourceDue(s)?' · revisar':' · em dia')+'</div></div><div>'+(s.url?'<a class="btn" target="_blank" rel="noopener" href="'+s.url+'">Fonte ↗</a>':'<span class="meta">Gmail / descoberta</span>')+'</div></div>'}).join("")+'</div>'}
function odetail(id){let o=opp(id);if(!o)return home();let hist=o.verificationHistory||[],direct=(o.story||[]).map(story).filter(Boolean),suggested=D.stories.filter(s=>!(o.story||[]).includes(s.id)&&(s.themes||[]).some(t=>(o.themes||[]).includes(t))).map(s=>({s,shared:(s.themes||[]).filter(t=>(o.themes||[]).includes(t))})).sort((a,b)=>b.shared.length-a.shared.length).slice(0,5);return'<button class="back" onclick="history.back()">← voltar</button><div class="detail"><div class="eyebrow">'+o.org+'</div><h1 class="detailtitle">'+o.title+'</h1>'+stateMark("opportunity",o.id)+stateControl("opportunity",o.id)+'<p class="lede">'+o.desc+'</p><div class="kv"><b>Status</b><div>'+badge(o.status,false)+' '+badge(o.deadlineStatus,false)+'</div></div><div class="kv"><b>Prontidão</b><div>'+badge(readiness(o),false)+'</div></div><div class="kv"><b>Prazo</b><div>'+(o.deadline?fmt(o.deadline):"Não confirmado / contínuo")+'</div></div><div class="kv"><b>Elegibilidade</b><div>'+badge(o.eligibility,false)+'</div></div><div class="kv"><b>Aderência PLOT.</b><div><span class="score">'+o.fit+'/10</span></div></div><div class="kv"><b>Temas</b><div>'+o.themes.map(x=>badge(x)).join("")+'</div></div>'+(o.value?'<div class="kv"><b>Valor</b><div>'+o.value+'</div></div>':"")+(o.duration?'<div class="kv"><b>Duração</b><div>'+o.duration+'</div></div>':"")+(o.modality?'<div class="kv"><b>Modalidade</b><div>'+o.modality+'</div></div>':"")+(o.opens?'<div class="kv"><b>Abertura</b><div>'+fmt(o.opens)+'</div></div>':"")+(o.documents?.length?'<div class="kv"><b>Documentos</b><div>'+o.documents.join("<br>")+'</div></div>':"")+(o.restrictions?.length?'<div class="kv"><b>Restrições</b><div>'+o.restrictions.join("<br>")+'</div></div>':"")+'<div class="kv"><b>Pautas relacionadas</b><div>'+(o.story.length?o.story.map(x=>'<a href="#pauta/'+x+'">'+story(x).title+'</a>').join("<br>"):"Nenhuma")+'</div></div><div class="kv"><b>Última verificação</b><div>'+fmt(o.verified)+' · '+freshness(o)+'</div></div>'+(hist.length?'<div class="kv"><b>Histórico</b><div>'+hist.map(h=>fmt(h.date)+' · '+h.status).join("<br>")+'</div></div>':"")+'</div><section class="intelligence"><div class="eyebrow">Conexões do Radar</div><h2>Pautas e esta oportunidade</h2><div class="intelgrid"><div class="intelpanel"><h3>Vínculos cadastrados</h3>'+(direct.length?direct.map(s=>'<a class="intelitem" href="#pauta/'+s.id+'"><b>'+s.title+'</b><span>'+stateMark("story",s.id)+'</span></a>').join(""):'<p class="meta">Nenhuma pauta vinculada diretamente.</p>')+'</div><div class="intelpanel"><h3>Possíveis relações por tema</h3>'+(suggested.length?suggested.map(x=>'<a class="intelitem" href="#pauta/'+x.s.id+'"><b>'+x.s.title+'</b><span>temas em comum: '+x.shared.join(", ")+'</span></a>').join(""):'<p class="meta">Nenhuma relação adicional encontrada.</p>')+'</div></div><p class="meta intelrule">Relações por tema são pistas de navegação, não recomendações de candidatura nem vínculos editoriais automáticos.</p></section><div class="detail"><p><a class="btn primary" target="_blank" rel="noopener" href="'+o.rules+'">Fonte oficial ↗</a>'+(o.apply?'<a class="btn" target="_blank" rel="noopener" href="'+o.apply+'">Inscrição ↗</a>':"")+'</p></div>'}
function sdetail(id){let s=story(id);if(!s)return stories();let os=D.opportunities.filter(o=>o.story.includes(id)&&o.status!=="encerrada"&&editorialState("opportunity",o.id)?.state!=="sem_interesse"),ds=D.datasets.filter(d=>d.story.includes(id));return'<button class="back" onclick="history.back()">← voltar</button><div class="detail"><div class="eyebrow">'+s.status+'</div><h1 class="detailtitle">'+s.title+'</h1>'+stateMark("story",s.id)+stateControl("story",s.id)+'<p class="lede">'+s.summary+'</p></div>'+submissionHistory(s.id)+'<h2>Mapa de investigação</h2><p class="meta">Cobertura operacional das etapas da pauta com as bases já cadastradas. Lacunas aparecem explicitamente e não são preenchidas por inferência.</p>'+storyKitHTML(s)+'<h2>Oportunidades relacionadas</h2>'+(os.length?'<div class="list">'+os.map(orow).join("")+'</div>':'<p class="meta">Nenhuma compatibilidade ativa.</p>')+'<div class="warning"><b>Regra editorial:</b> não adaptar artificialmente a pauta ao edital.</div><h2>Todas as bases relacionadas</h2>'+(ds.length?datasets(false,ds):'<p class="meta">Nenhuma base vinculada.</p>')}
function filters(){let q=document.querySelector("#q"),t=document.querySelector("#type"),e=document.querySelector("#elig"),pe=document.querySelector("#personal"),ac=document.querySelector("#act"),th=document.querySelector("#theme"),s=document.querySelector("#sort"),list=document.querySelector("#olist"),preset=route().split("/")[1]||"",labels={decidir:"Para decidir",preparar:"Em preparação",andamento:"Em andamento",prazo30:"Encerram em 30 dias",rolling:"Fluxo contínuo",acionaveis:"Acionáveis"};function presetOk(o){let st=editorialState("opportunity",o.id)?.state;if(preset==="decidir")return !st;if(preset==="preparar")return st==="vou_fazer";if(preset==="andamento")return st==="em_andamento";if(preset==="prazo30")return o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=30;if(preset==="rolling")return o.deadlineStatus==="rolling";if(preset==="acionaveis")return ["preparar","avaliar/aplicar"].includes(action(o));return st!=="sem_interesse"}function personalOk(o){let st=editorialState("opportunity",o.id)?.state||"";return !pe.value||(pe.value==="decidir"?!st:st===pe.value)}function go(){let a=D.opportunities.filter(o=>presetOk(o)&&!["encerrada","descartada"].includes(o.status)&&[o.title,o.org,...o.themes,...o.story.map(x=>story(x)?.title||"")].join(" ").toLowerCase().includes(q.value.toLowerCase())&&(!t.value||o.type===t.value)&&(!e.value||o.eligibility===e.value)&&personalOk(o)&&(!ac.value||action(o)===ac.value)&&(!th.value||o.themes.includes(th.value)));a.sort(s.value==="fit"?(a,b)=>b.fit-a.fit:s.value==="fresh"?(a,b)=>(b.verified||"").localeCompare(a.verified||""):(a,b)=>(a.deadline||"9999").localeCompare(b.deadline||"9999"));list.innerHTML=(preset&&labels[preset]?'<div class="activepreset">Filtro ativo: <b>'+labels[preset]+'</b> <a href="#oportunidades">limpar ×</a></div>':"")+(a.map(orow).join("")||"<p>Nenhum resultado.</p>")}[q,t,e,pe,ac,th,s].forEach(x=>x.addEventListener("input",go));go()}

function validateRadar(){
 let errors=[],warnings=[],ids=new Set(),storyIds=new Set(D.stories.map(s=>s.id)),dateRx=/^\d{4}-\d{2}-\d{2}$/;
 const add=(level,kind,id,msg)=>(level==="error"?errors:warnings).push({kind,id,msg});
 D.opportunities.forEach(o=>{
  if(!o.id)add("error","oportunidade","sem-id","ID ausente"); else if(ids.has(o.id))add("error","oportunidade",o.id,"ID duplicado"); else ids.add(o.id);
  ["title","org","type","scope","status","eligibility"].forEach(k=>{if(!o[k])add("error","oportunidade",o.id,k+" ausente")});
  if(typeof o.fit!=="number"||o.fit<0||o.fit>10)add("error","oportunidade",o.id,"aderência fora de 0–10");
  if(!o.rules||!/^https?:\/\//.test(o.rules))add("error","oportunidade",o.id,"fonte oficial ausente/inválida");
  ["deadline","opens","verified"].forEach(k=>{if(o[k]&&!dateRx.test(o[k]))add("error","oportunidade",o.id,k+" em formato inválido")});
  (o.story||[]).forEach(x=>{if(!storyIds.has(x))add("error","oportunidade",o.id,"pauta inexistente: "+x)});
  if(!o.summary)add("warning","oportunidade",o.id,"resumo editorial próprio ainda não cadastrado");
  if(!o.verified)add("warning","oportunidade",o.id,"sem data de verificação");
 });
 let snames=new Set();
 D.sources.forEach(s=>{
  if(!s.name)add("error","fonte","sem-nome","nome ausente"); else if(snames.has(s.name))add("error","fonte",s.name,"nome duplicado"); else snames.add(s.name);
  ["type","scope","priority","cadence","category","lastChecked"].forEach(k=>{if(!s[k])add("error","fonte",s.name,k+" ausente")});
  if(s.url&&!/^https?:\/\//.test(s.url))add("error","fonte",s.name,"URL inválida");
  if(!["diária","semanal","quinzenal","mensal"].includes(s.cadence))add("error","fonte",s.name,"cadência inválida");
  if(s.lastChecked&&!dateRx.test(s.lastChecked))add("error","fonte",s.name,"lastChecked em formato inválido");
 });
 let dids=new Set();
 D.datasets.forEach(d=>{
  if(!d.id)add("error","base","sem-id","ID ausente"); else if(dids.has(d.id))add("error","base",d.id,"ID duplicado"); else dids.add(d.id);
  let kinds=["dataset","portal","catalog","system","curated-source"];
  if(!d.kind||!kinds.includes(d.kind))add("error","base",d.id,"tipo inválido ou ausente");
  if(!d.url||!/^https?:\/\//.test(d.url))add("error","base",d.id,"URL ausente/inválida");
  (d.story||[]).forEach(x=>{if(!storyIds.has(x))add("error","base",d.id,"pauta inexistente: "+x)});
  let m=datasetMeta(d),required=d.kind==="dataset"?["period","granularity","geoUnit","docs","lastChecked"]:d.kind==="system"?["docs","lastChecked"]:["docs","limitations","lastChecked"];required.forEach(k=>{if(!m[k])add("warning","base",d.id,k+" pendente")});
 });
 return{errors,warnings,checked:D.opportunities.length+D.datasets.length+D.stories.length+D.sources.length};
}
function quality(embedded=false){
 let q=validateRadar(),groups=[...q.errors.map(x=>({...x,level:"erro"})),...q.warnings.map(x=>({...x,level:"pendência"}))];
 return (embedded?"":head("Controle de qualidade","Validação do Radar","Checagem automática de integridade estrutural. Erros indicam quebra objetiva do schema; pendências indicam metadados que ainda precisam de confirmação editorial."))+
 '<div class="metrics qualitymetrics"><div class="metric"><b>'+q.checked+'</b><span>registros checados</span></div><div class="metric"><b>'+q.errors.length+'</b><span>erros estruturais</span></div><div class="metric"><b>'+q.warnings.length+'</b><span>pendências</span></div><div class="metric"><b>'+D.opportunities.filter(o=>o.summary).length+'</b><span>resumos próprios</span></div></div>'+
 (q.errors.length?'<div class="warning danger"><b>Atenção:</b> existem erros estruturais que devem ser corrigidos antes da próxima carga.</div>':'<div class="warning ok"><b>Estrutura válida:</b> nenhum erro crítico detectado.</div>')+
 '<div class="list qualitylist">'+groups.map(x=>'<div class="row"><div><span class="badge">'+x.level+'</span><h3>'+x.id+'</h3></div><div>'+x.kind+'</div><div>'+x.msg+'</div><div></div></div>').join("")+'</div>';
}

function closeNav(){document.querySelector("#nav")?.classList.remove("open")}function render(){closeNav();nav();renderAuth();let [base,id]=route().split("?")[0].split("/");if(base==="oportunidade")app.innerHTML=odetail(id);else if(base==="base")app.innerHTML=datasetDetail(id);else if(base==="pauta")app.innerHTML=sdetail(id);else if(base==="tema")app.innerHTML=themePage(id);else if(base==="metodologia")app.innerHTML=methods(id||"fontes");else app.innerHTML=({visao:home,oportunidades:opportunities,pautas:stories,dados:datasets,pipeline,matrix:matrix,matriz:matrix,calendario:calendar,arquivo:archive}[base]||home)();if(base==="oportunidades")filters();if(base==="pautas")storyFilters();if(base==="dados")dataFilters();window.scrollTo(0,0)}
window.addEventListener("hashchange",render);document.querySelector("#menu").onclick=()=>{let n=document.querySelector("#nav"),open=n.classList.toggle("open");document.querySelector("#menu").setAttribute("aria-expanded",String(open));document.querySelector("#menu").setAttribute("aria-label",open?"Fechar menu":"Abrir menu")};document.querySelector("#nav").addEventListener("click",e=>{if(e.target.closest("a"))closeNav()});render();
